<script setup>
import {ref,computed} from 'vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},points:{type:Array,default:()=>[]},suggestions:{type:Array,default:()=>[]},disabled:Boolean});const emit=defineEmits(['update:modelValue']);const query=ref('');
const visible=computed(()=>props.points.filter(p=>(p.name+' '+(p.aliases||[]).join(' ')).includes(query.value.trim())));
const pending=computed(()=>props.suggestions.filter(p=>!props.modelValue.includes(p.id)));
function toggle(id){if(props.disabled)return;emit('update:modelValue',props.modelValue.includes(id)?props.modelValue.filter(v=>v!==id):[...props.modelValue,id])}
function names(ids){return ids.map(id=>props.points.find(p=>p.id===id)?.name||id).join('、')}
</script>
<template><section class="knowledge-picker"><label class="field-label">关联课程知识点<Input v-model="query" placeholder="搜索知识点或别名" :disabled="disabled"/></label><p v-if="modelValue.length" class="knowledge-confirmed">已关联：{{ names(modelValue) }}</p><p v-else class="model-model-name">尚未关联</p><div class="knowledge-options"><label v-for="p in visible" :key="p.id"><input type="checkbox" :checked="modelValue.includes(p.id)" :disabled="disabled" @change="toggle(p.id)"/><span><strong>{{ p.name }}</strong><small v-if="p.prerequisites?.length">前置：{{ names(p.prerequisites) }}</small></span></label></div><p v-if="!visible.length" class="ai-empty">没有匹配的知识点</p><details v-if="pending.length"><summary>待确认建议 　 {{ pending.length }}</summary><div v-for="p in pending" :key="p.id" class="knowledge-suggestion"><span>{{ p.name }}<InfoTip label="关联建议依据">命中{{ p.source==='alias'?'别名':'名称' }}：{{ p.matchedNames.join('、') }}。确认后才写入草稿，不自动修改历史版本。</InfoTip></span><Button variant="outline" size="sm" :disabled="disabled" @click="toggle(p.id)">确认关联</Button></div></details></section></template>
